<script setup lang="ts">
import {onMounted,ref} from 'vue';import {api,apiMessage} from '@/api/client';import AggregateTrend from './AggregateTrend.vue';import {metricRange,type GrowthReport,type WebsiteReport} from '@/metrics';
const range=ref(metricRange()),growth=ref<GrowthReport|null>(null),website=ref<WebsiteReport|null>(null),busy=ref(false),error=ref('');
async function load(){if(busy.value)return;busy.value=true;error.value='';try{const [a,b]=await Promise.all([api.get<GrowthReport>('/admin/metrics/growth',{params:range.value}),api.get<WebsiteReport>('/admin/metrics/website',{params:range.value})]);growth.value=a.data;website.value=b.data;}catch(e){error.value=apiMessage(e);growth.value=null;website.value=null;}finally{busy.value=false;}}
function preset(days:number){range.value=metricRange(days);if(days===0){const d=new Date(range.value.to+'T00:00:00Z');d.setUTCDate(d.getUTCDate()-1);range.value={from:d.toISOString().slice(0,10),to:d.toISOString().slice(0,10)};}void load();}onMounted(load);
</script>
<template><section class="metrics section" aria-label="注册增长与官网访问"><h2>注册增长与官网访问</h2><nav class="button-row" aria-label="统计快捷范围"><button class="btn" :disabled="busy" @click="preset(0)">昨日</button><button class="btn" :disabled="busy" @click="preset(7)">近7日</button><button class="btn" :disabled="busy" @click="preset(30)">近30日</button></nav><form @submit.prevent="load"><label>指标开始日期<input v-model="range.from" type="date" :max="range.to" required/></label><label>指标结束日期<input v-model="range.to" type="date" :min="range.from" :max="metricRange().to" required/></label><button class="btn" :disabled="busy">读取统计</button></form><p v-if="error" role="alert">{{error}}</p><p v-if="busy" role="status">正在读取有界聚合…</p><template v-if="growth"><p class="helper-text">北京时间 {{growth.from}} 至 {{growth.to}} · 更新 {{new Date(growth.observedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}}</p><dl><div><dt>累计注册账号</dt><dd>{{growth.totalRegistered}}</dd></div><div><dt>其中停用账号</dt><dd>{{growth.disabled}}</dd></div><div><dt>范围内新增</dt><dd>{{growth.registeredInRange}}</dd></div></dl><AggregateTrend title="每日新增注册" :from="growth.from" :to="growth.to" :rows="growth.days.map(d=>({date:d.date,value:d.registered}))" :meaning="growth.meaning"/></template><template v-if="website"><p>{{website.enabled?'官网自愿分析已启用':'官网自愿分析未启用，历史不补造'}} · 只记录主动参与者的介绍页有效浏览；不会把健康检查或API轮询当PV。</p><dl><div><dt>参与分析浏览量PV</dt><dd>{{website.pv}}</dd></div><div><dt>日去重访客合计</dt><dd>{{website.dailyVisitorSum}}</dd></div><div><dt>无法估算访客的浏览</dt><dd>{{website.withoutVisitorEstimate}}</dd></div></dl><AggregateTrend title="官网有效浏览PV" :from="website.from" :to="website.to" :rows="website.days.map(d=>({date:d.date,value:d.pv}))" meaning="只展示实际采集日期；拒绝分析、拦截、机器人与清缓存会影响统计，不等于网站全部请求。"/><AggregateTrend title="匿名访客估算（日去重）" :from="website.from" :to="website.to" :rows="website.days.map(d=>({date:d.date,value:d.dailyVisitors}))" :meaning="website.visitorMeaning"/></template></section></template>
<style scoped>.metrics{padding:24px;margin:28px 0;background:#fff}.metrics h2{font-size:1.4rem}.metrics form{display:flex;gap:16px;align-items:end;flex-wrap:wrap;margin:20px 0}.metrics label{display:grid;gap:8px;font-size:.8rem}.metrics input{min-width:0}.metrics dl{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));border:1px solid var(--line)}.metrics dl>div{padding:16px;border-right:1px solid var(--line);min-width:0}.metrics dt{font-size:.8rem}.metrics dd{margin:12px 0 0;font-size:2rem;color:#002FA7;overflow-wrap:anywhere}.metrics p{font-size:.85rem;line-height:1.8}@media(max-width:700px){.metrics{padding:16px}.metrics form{display:grid;grid-template-columns:minmax(0,1fr);width:100%}.metrics dl{grid-template-columns:minmax(0,1fr)}.metrics dl>div{border-bottom:1px solid var(--line)}.metrics label{min-width:0}}</style>
